def installer(apps, schema_editor):
    EtapeStandard = apps.get_model("industriel", "EtapeStandard")
    NatureCout = apps.get_model("couts", "NatureCout")
    etapes = {}
    for code, libelle, ordre, description in ETAPES:
        etapes[code] = EtapeStandard.objects.filter(code=code).first() or EtapeStandard.objects.create(
            code=code, libelle=libelle, phase="SITE", ordre_reference=ordre, description=description,
        )
    rang = max((int(c[4:]) for c in NatureCout.objects.values_list("code", flat=True) if c[4:].isdigit()), default=0)
    for libelle, etape, economique, inducteur, justification in NATURES:
        if NatureCout.objects.filter(libelle=libelle).exists():
            continue
        rang += 1
        NatureCout.objects.create(
            code=f"NAT-{rang:03d}", libelle=libelle, etape=etapes[etape], categorie="PRODUCTION",
            categorie_economique=economique, traitement="INDIRECT", inducteur=inducteur, justification=justification,
        )


